export const CREATING_WITH_AI_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu AI generatif, cara ia menghasilkan, memberi instruksi
{n:1,type:"mcq",micro:"AI generatif",q:"'AI generatif' berbeda dari AI pengklasifikasi karena ia...",options:["Menghasilkan konten baru: teks, gambar, suara, atau musik","Hanya memberi label ya/tidak","Tidak pernah salah"],answer:0,explain:"AI generatif membuat keluaran baru, bukan sekadar memilih kategori dari yang sudah ada.",hint:"Membuat sesuatu yang baru vs memilah yang sudah ada."},
{n:2,type:"mcq",micro:"Cara model teks menghasilkan",q:"Model bahasa menghasilkan tulisan dengan cara...",options:["Menyalin paragraf utuh dari sebuah buku","Memprediksi potongan kata berikutnya berulang kali, berdasarkan pola dari teks dalam jumlah besar","Bertanya ke manusia"],answer:1,explain:"Kalimat dibangun kata demi kata: tiap langkah, model memilih kelanjutan yang paling mungkin secara pola.",hint:"Bayangkan papan ketik prediktif diperbesar ribuan kali."},
{n:3,type:"mcq",micro:"Cara model gambar menghasilkan",q:"Model gambar generatif membuat gambar dengan...",options:["Menggambar dengan tangan robot","Mengambil foto dari internet lalu menempelnya","Menyusun gambar baru dari pola visual yang dipelajari dari jutaan gambar berlabel"],answer:2,explain:"Model belajar hubungan antara kata & pola visual, lalu menghasilkan gambar baru yang cocok dengan deskripsi.",hint:"Apakah gambar yang dihasilkan sudah ada persis di suatu tempat sebelumnya?"},
{n:4,type:"mcq",micro:"Instruksi (prompt)",q:"'Prompt' atau instruksi untuk AI generatif adalah...",options:["Deskripsi apa yang kamu ingin AI hasilkan","Nama model AI","Tombol untuk memulai"],answer:0,explain:"Kualitas & kecocokan keluaran sangat bergantung pada seberapa jelas & lengkap instruksimu.",hint:"Apa yang kamu ketik untuk memberi tahu AI apa yang kamu mau?"},
{n:5,type:"mcq",micro:"Instruksi yang lebih baik",q:"Manakah instruksi yang kemungkinan menghasilkan gambar paling sesuai keinginan?",options:["'Gambar kucing.'","'Gambar kucing oranye gemuk sedang tidur di atas tumpukan buku, gaya ilustrasi kartun sederhana, latar putih.'","'kucing'"],answer:1,explain:"Detail (subjek, tindakan, gaya, latar, warna) mengarahkan AI ke hasil yang kamu bayangkan.",hint:"Semakin lengkap deskripsimu, semakin dekat hasilnya dengan yang kamu inginkan."},
{n:6,type:"order",micro:"Alur membuat sesuatu dengan AI generatif",q:"Urutkan langkah membuat karya dengan bantuan AI generatif.",items:["Perjelas apa yang kamu ingin buat & untuk apa","Tulis instruksi yang spesifik (subjek, gaya, format, batasan)","Tinjau hasil; perbaiki instruksi atau minta variasi bila belum pas","Sunting, pilih, & kembangkan hasilnya jadi karya finalmu; periksa hak & kejujuran"],answer:[0,1,2,3],explain:"Perjelas tujuan → instruksi spesifik → iterasi → sunting & selesaikan dengan pertimbangan etis.",hint:"Kamu perlu tahu apa yang kamu buat sebelum bisa memberi instruksi yang baik."},
{n:7,type:"mcq",micro:"Iterasi",q:"Kalau hasil pertama AI belum sesuai, cara yang baik:",options:["Menyerah","Pakai apa adanya","Beri instruksi lebih spesifik atau perbaikan ('lebih cerah', 'buat lebih pendek', 'ubah gayanya jadi realistis')"],answer:2,explain:"Membuat dengan AI bersifat berulang: instruksi → hasil → perbaikan → hasil lebih baik.",hint:"Bagaimana kamu memberi tahu apa yang kurang dari hasil pertama?"},
{n:8,type:"mcq",micro:"Hasil bervariasi",q:"Kamu memberi instruksi yang sama dua kali & mendapat gambar/teks berbeda. Ini...",options:["Normal — model generatif menambah unsur pilihan/keacakan, jadi tiap kali bisa berbeda","Berarti model rusak","Tidak mungkin terjadi"],answer:0,explain:"Variasi keluaran adalah sifat model generatif. Kamu bisa menghasilkan beberapa versi & memilih yang terbaik.",hint:"Apakah AI selalu menghasilkan keluaran yang identik untuk instruksi yang sama?"},
{n:9,type:"mcq",micro:"Halusinasi dalam teks",q:"Model teks bisa menghasilkan fakta, nama buku, atau kutipan yang terdengar meyakinkan tapi sebenarnya tidak ada. Ini disebut...",options:["Kesalahan ketik","'Halusinasi' — keluaran masuk akal tapi tidak berdasar; perlu verifikasi","Kebohongan yang disengaja"],answer:1,explain:"Model memprediksi teks yang polanya pas, jadi kadang 'mengarang' detail. Untuk fakta, selalu cek sumber independen.",hint:"Terdengar benar + tidak nyata = istilahnya apa?"},
{n:10,type:"tf",micro:"AI generatif belajar dari karya manusia",q:"Benar atau Salah: AI generatif menciptakan gaya & polanya sendiri dari nol, tanpa mempelajari apa pun dari karya buatan manusia.",answer:false,explain:"Sebaliknya — kemampuan model mencerminkan pola dari karya manusia (tulisan, gambar, musik) dalam jumlah sangat besar yang jadi data latihnya. Ini juga sumber perdebatan tentang hak cipta & atribusi.",hint:"Dari mana model belajar seperti apa 'gaya cat air' atau 'gaya penulisan formal'?"},
{n:11,type:"mcq",micro:"AI generatif sebagai alat bantu",q:"Cara paling produktif memandang AI generatif dalam berkarya:",options:["Pembuat karya utuh yang menggantikanmu","Sesuatu yang tidak boleh dipakai sama sekali","Alat bantu untuk mempercepat draf, mengeksplorasi ide, & menghasilkan bahan mentah — yang lalu kamu pilih, sunting, & kembangkan"],answer:2,explain:"Nilai terbaik muncul saat AI mempercepat & memperluas prosesmu, sementara arah, penilaian, & sentuhan akhir tetap milikmu.",hint:"Apakah AI mengerjakan seluruh karya, atau membantu di bagian tertentu?"},
{n:12,type:"mcq",micro:"Menyunting hasil AI",q:"Setelah AI menghasilkan draf teks, langkah penting:",options:["Baca, perbaiki kesalahan, sesuaikan dengan suaramu & tujuanmu, & verifikasi fakta — bukan menyalin apa adanya","Kirim langsung","Ubah beberapa kata lalu klaim orisinal"],answer:0,explain:"Draf AI adalah titik awal, bukan produk final. Penyuntingan mengubahnya menjadi karya yang benar-benar kamu pertanggungjawabkan.",hint:"Apa yang harus kamu lakukan pada draf sebelum menyerahkannya?"},
{n:13,type:"tf",micro:"Kamu bertanggung jawab atas hasil akhir",q:"Benar atau Salah: Kalau kamu memakai AI untuk membantu membuat sesuatu & membagikannya, kamu bertanggung jawab atas isi, kebenaran, & dampaknya.",answer:true,explain:"AI adalah alat. Pembuat & penyebar karya bertanggung jawab atas hasilnya, termasuk kesalahan atau kerugian yang ditimbulkannya.",hint:"Nama siapa yang tertera pada karya itu?"},
{n:14,type:"mcq",micro:"Kejujuran: menandai karya AI",q:"Kalau sebagian besar gambar/tulisan dibuat AI & konteksnya bisa membuat orang mengira itu buatanmu sendiri atau foto nyata...",options:["Klaim sepenuhnya sebagai karyamu","Sebutkan bahwa AI dipakai (atau tandai gambarnya) — transparansi mencegah menyesatkan orang","Diamkan saja"],answer:1,explain:"Menyesatkan orang tentang asal-usul sebuah karya (buatan manusia vs AI, nyata vs sintetis) tidak jujur.",hint:"Apakah orang yang melihat karyamu akan salah paham tentang bagaimana ia dibuat?"},
{n:15,type:"mcq",micro:"Lomba & orisinalitas",q:"Menyerahkan karya yang sebagian besar dibuat AI ke lomba yang menilai kreativitas & kemampuan peserta sendiri...",options:["Boleh asal tidak ketahuan","Selalu boleh, AI hanya alat","Adalah ketidakjujuran — konteks itu menilai kemampuan & ekspresi orangnya"],answer:2,explain:"Di konteks yang inti-nya menilai orisinalitas & keterampilan peserta, mengaku karya AI sebagai buatan sendiri melanggar aturan main.",hint:"Apa yang sebenarnya dinilai lomba itu?"},
{n:16,type:"mcq",micro:"Membuat konten tentang orang nyata",q:"Memakai AI untuk membuat gambar/suara/video seseorang tanpa izin, terutama yang bisa memalukan atau menyesatkan...",options:["Melanggar hak & martabat orang itu, & bisa berkonsekuensi serius","Lucu & tidak apa-apa","Boleh kalau tidak disebar luas"],answer:0,explain:"Membuat media sintetis tentang orang nyata tanpa izin bisa sangat merugikan mereka.",hint:"Bagaimana perasaanmu kalau ada gambar/video palsu 'kamu'?"},
{n:17,type:"mcq",micro:"AI untuk mengeksplorasi ide",q:"Pemakaian AI generatif yang aman & berguna dalam berkarya:",options:["Menyalin gaya seniman tertentu untuk dijual sebagai karya seniman itu","Menghasilkan banyak variasi awal (judul, sketsa konsep, alur cerita) untuk kamu pilih & kembangkan","Membuat seluruh karya lalu menyerahkannya tanpa perubahan"],answer:1,explain:"AI bagus untuk memperluas ruang ide di awal. Penyaringan, pengembangan, & eksekusi tetap milikmu.",hint:"Untuk apa AI berguna di tahap 'mencari banyak kemungkinan'?"},
{n:18,type:"mcq",micro:"Batas kemampuan model teks",q:"Untuk tugas yang butuh angka atau tanggal yang sangat tepat, model teks generatif...",options:["Selalu akurat","Tidak bisa menghasilkan angka","Rawan keliru — verifikasi dengan sumber tepercaya atau alat hitung"],answer:2,explain:"Model memprediksi teks yang 'terdengar benar', bukan menghitung atau mengambil dari basis data terverifikasi.",hint:"Mana yang lebih rawan: gaya penulisan, atau statistik spesifik?"},
{n:19,type:"mcq",micro:"Menjaga suara sendiri",q:"Kalau tulisan/gambarmu yang dibantu AI terasa 'bukan seperti kamu', itu tanda...",options:["Kamu mungkin terlalu mengandalkan keluaran AI — kembangkan dengan gaya, sudut pandang, & pilihan pribadimu","Karya yang baik memang tidak bersuara","Tidak masalah, yang penting rapi"],answer:0,explain:"Karya yang bermakna punya suara. Kalau AI mendominasi, hasilnya terasa generik & bukan milikmu.",hint:"Apakah karya itu terasa seperti ekspresimu?"},
{n:20,type:"open",micro:"Membuat instruksi yang baik",q:"Kamu ingin AI membantu membuat ilustrasi sampul untuk cerita pendek karyamu tentang seorang anak yang menemukan taman rahasia. Tulis SATU instruksi yang spesifik (subjek, suasana, gaya, warna, format, & apa yang TIDAK kamu inginkan), lalu tuliskan 2 hal yang akan kamu lakukan pada hasilnya sebelum memakainya.",sample:"Instruksi: 'Ilustrasi sampul buku anak: seorang anak berusia sekitar 10 tahun berdiri di ambang gerbang berkarat yang terbuka menuju taman yang rimbun & penuh cahaya, dilihat dari belakang anak itu. Suasana ajaib & penuh rasa ingin tahu, waktu sore keemasan. Gaya ilustrasi cat air lembut dengan garis tangan halus. Palet hijau, emas, & cokelat hangat. Format potret, ada ruang kosong di bagian atas untuk judul. Hindari: gaya kartun kasar, warna neon, teks/tulisan di dalam gambar.' Yang kulakukan pada hasil: (1) memilih dari beberapa versi & menyuntingnya (memangkas, menyesuaikan warna) agar cocok dengan bayanganku & dengan judul; (2) memastikan gambarnya tidak meniru gaya khas seniman tertentu yang bisa dikenali, & mencantumkan bahwa sampul dibuat dengan bantuan AI bila diminta.",explain:"Instruksi baik menyebut subjek, komposisi, suasana, gaya, palet, format, & pengecualian. Rencana pasca-produksi menunjukkan penyuntingan (karya jadi milikmu) & pertimbangan etis (tidak meniru seniman spesifik, transparansi).",hint:"Sebutkan juga apa yang TIDAK kamu inginkan — itu sering sama pentingnya."},

// FASE B — PEMAHAMAN / PIKTORIAL (21-40): teknik, jenis karya, kolaborasi manusia+AI
{n:21,type:"mcq",micro:"Memberi contoh gaya",q:"Kalau kamu ingin AI menulis dengan gaya tertentu, cara efektif:",options:["Tidak mungkin diatur","Beri satu-dua contoh gaya yang kamu maksud & minta ia mengikuti polanya","Berharap ia menebak"],answer:1,explain:"Menunjukkan contoh sering lebih efektif daripada mendeskripsikan gaya dengan kata-kata.",hint:"Lebih mudah menjelaskan gaya lewat deskripsi atau lewat contoh?"},
{n:22,type:"mcq",micro:"Membangun bertahap",q:"Untuk karya besar (cerita panjang, proyek visual), pendekatan yang lebih baik:",options:["Minta seluruh karya dalam satu instruksi & pakai apa adanya","Jangan pakai AI untuk karya besar","Bangun bertahap: minta kerangka → kembangkan satu bagian → minta masukan → lanjut — bukan minta seluruhnya sekaligus"],answer:2,explain:"Membangun bertahap menjaga kamu tetap pengarah utama & memungkinkan penyempurnaan di tiap tahap.",hint:"Bagaimana memakai AI tanpa menjadikannya pembuat karya sebenarnya?"},
{n:23,type:"classify",micro:"Jenis bantuan AI generatif",q:"Kelompokkan tiap pemakaian sebagai 'Menghasilkan bahan mentah', 'Menyunting/memperbaiki', atau 'Memberi umpan balik'.",items:["Membuat 10 sketsa konsep karakter untuk kamu pilih","Memperbaiki tata bahasa & memperjelas kalimat draf-mu","Menunjukkan kelemahan alur ceritamu & bagian yang membingungkan"],groups:["Menghasilkan bahan mentah","Menyunting/memperbaiki","Memberi umpan balik"],answer:{"Menghasilkan bahan mentah":["Membuat 10 sketsa konsep karakter untuk kamu pilih"],"Menyunting/memperbaiki":["Memperbaiki tata bahasa & memperjelas kalimat draf-mu"],"Memberi umpan balik":["Menunjukkan kelemahan alur ceritamu & bagian yang membingungkan"]},explain:"AI bisa membantu di tiga peran berbeda; menyadari mana yang kamu pakai membantu menjaga kepenulisanmu.",hint:"Apakah AI membuat sesuatu yang baru, memperbaiki milikmu, atau mengomentari milikmu?"},
{n:24,type:"mcq",micro:"Menggabungkan hasil AI dengan karya sendiri",q:"Cara sehat memakai bahan dari AI dalam karyamu:",options:["Ambil bagian yang berguna, gabung dengan idemu, ubah & kembangkan sampai menjadi ekspresi yang khas kamu","Tempel apa adanya tanpa perubahan","Buang semua yang dari AI"],answer:0,explain:"AI menyediakan bahan; kamu yang mengubahnya menjadi karya dengan visi & sentuhan pribadi.",hint:"Apa yang membuat sebuah karya terasa 'milikmu'?"},
{n:25,type:"mcq",micro:"Meniru gaya seniman tertentu",q:"Meminta AI membuat karya 'dengan gaya persis seniman [nama] yang masih hidup' untuk dipakai/dijual...",options:["Wajib dilakukan untuk hasil terbaik","Bermasalah secara etika — memanfaatkan kerja & identitas seniman itu tanpa izin atau kompensasi; hindari meniru gaya khas orang tertentu","Sepenuhnya baik"],answer:1,explain:"Meniru 'gaya khas' seniman yang dikenali menimbulkan masalah hak & keadilan, terutama untuk penggunaan komersial atau yang menyesatkan.",hint:"Bagaimana perasaan seorang seniman kalau gayanya dipakai orang lain tanpa izin untuk cari uang?"},
{n:26,type:"mcq",micro:"AI untuk mengatasi 'kebuntuan'",q:"Saat kamu buntu memulai sebuah tulisan, memakai AI untuk...",options:["Menulis seluruh tulisan untukmu","Menyerah pada tulisan itu","Menghasilkan beberapa kemungkinan pembuka sebagai pemantik — lalu kamu menulis versimu sendiri dari sana"],answer:2,explain:"AI bisa membantu melewati hambatan awal; tulisan sebenarnya tetap kamu kerjakan agar keterampilan & suaramu terbangun.",hint:"Bagaimana AI membantumu MEMULAI tanpa menulis untukmu?"},
{n:27,type:"mcq",micro:"Verifikasi konten faktual",q:"Kamu memakai AI membantu menulis artikel informatif. Untuk setiap fakta/angka yang AI berikan:",options:["Cek di sumber tepercaya yang independen sebelum memasukkannya ke artikel","Percaya karena terdengar meyakinkan","Salin langsung"],answer:0,explain:"AI bisa 'mengarang' detail. Artikel yang kamu terbitkan mencerminkan kredibilitasmu, jadi verifikasi wajib.",hint:"Apa yang bisa terjadi pada reputasimu kalau artikelmu berisi fakta palsu dari AI?"},
{n:28,type:"tf",micro:"Kreativitas datang dari pilihan & pengembangan",q:"Benar atau Salah: Nilai kreatif sebuah karya sepenuhnya terletak pada bahan mentahnya, bukan pada pilihan-pilihan yang kamu buat (apa yang diambil, dibuang, diubah, dikombinasikan, & ke mana dikembangkan).",answer:false,explain:"Justru sebaliknya — nilai kreatif sering terletak pada pilihan-pilihan itu. AI bisa memberi bahan; kekhasan & kedalaman datang dari kurasi, penyuntingan, & visi pribadimu.",hint:"Apakah dua orang dengan bahan mentah yang sama pasti menghasilkan karya yang sama?"},
{n:29,type:"mcq",micro:"Menghindari keseragaman",q:"Kalau semua orang memakai AI yang sama dengan instruksi serupa, hasilnya cenderung...",options:["Selalu terbaik","Mirip satu sama lain ('generik') — kekhasan butuh instruksi yang lebih pribadi & pengembangan yang kamu lakukan sendiri","Selalu unik"],answer:1,explain:"AI menghasilkan keluaran 'rata-rata' dari polanya. Untuk menonjol, tambahkan visi & sentuhan yang khas kamu.",hint:"Kalau semua minta 'gambar naga keren', seberapa unik hasilnya?"},
{n:30,type:"order",micro:"Menyempurnakan karya lewat iterasi",q:"Urutkan langkah menyempurnakan hasil AI yang belum pas.",items:["Identifikasi persis apa yang kurang (gaya? komposisi? nada? panjang?)","Beri instruksi perbaikan yang spesifik atau minta beberapa variasi","Pilih versi terbaik & sunting sendiri untuk sentuhan akhir","Periksa kejujuran (tandai bila perlu) & hak sebelum membagikan"],answer:[0,1,2,3],explain:"Identifikasi kekurangan → instruksi/variasi → pilih & sunting → cek etika & hak.",hint:"Kamu perlu tahu apa yang kurang sebelum bisa memperbaikinya."},
{n:31,type:"mcq",micro:"AI untuk aksesibilitas kreatif",q:"AI generatif bisa membantu orang yang...",options:["Tidak punya ide sama sekali","Ingin menghindari semua usaha","Punya ide tapi keterbatasan keterampilan teknis (menggambar, notasi musik) untuk mewujudkan sebagian visinya — sambil tetap belajar & mengembangkan keterampilan itu"],answer:2,explain:"AI bisa menurunkan hambatan untuk mengekspresikan ide. Ini positif, asal tidak menggantikan pembelajaran keterampilan yang ingin kamu kuasai.",hint:"Bagaimana AI bisa membantu orang mewujudkan ide yang tadinya di luar jangkauan teknis mereka?"},
{n:32,type:"mcq",micro:"Menghormati hak orang lain dalam karya",q:"Sebelum membuat karya AI yang melibatkan wajah, nama, atau ciri khas orang nyata yang kamu kenal:",options:["Minta izin mereka; hindari yang bisa memalukan atau menyesatkan","Tidak perlu izin, mereka temanmu","Buat saja, itu hanya seni"],answer:0,explain:"Orang punya hak atas citra & identitasnya. Menghormati itu dalam karya AI adalah tanggung jawabmu.",hint:"Apakah temanmu setuju wajahnya kamu masukkan ke gambar apa pun yang kamu buat?"},
{n:33,type:"mcq",micro:"Menggunakan AI untuk belajar keterampilan",q:"Kamu ingin belajar menggambar. Cara memakai AI yang MENDUKUNG (bukan menghambat) pembelajaran:",options:["Hindari AI sepenuhnya","Minta AI menjelaskan prinsip (perspektif, proporsi), memberi referensi, & memberi masukan pada gambarmu sendiri — bukan menggambar untukmu","Selalu minta AI menggambar & tidak pernah berlatih sendiri"],answer:1,explain:"AI sebagai tutor/pemberi masukan mempercepat belajar; AI sebagai pengganti latihan menghentikannya.",hint:"Apa bedanya 'jelaskan prinsip perspektif' dengan 'gambarkan ini untukku'?"},
{n:34,type:"tf",micro:"Hasil AI bisa jadi titik awal, bukan titik akhir",q:"Benar atau Salah: Keluaran AI generatif sering paling berharga sebagai titik awal atau bahan yang kamu kembangkan, bukan sebagai produk final yang langsung dipakai.",answer:true,explain:"Draf, sketsa, & variasi dari AI mempercepat proses; visi, kurasi, & penyempurnaan yang membuat karya bernilai & khas.",hint:"Apakah draf pertama biasanya karya terbaik?"},
{n:35,type:"mcq",micro:"Instruksi negatif",q:"Menyebutkan apa yang TIDAK kamu inginkan ('tanpa teks di gambar', 'hindari warna gelap', 'jangan gaya realistis') berguna karena...",options:["Membingungkan AI","Tidak berpengaruh","Mempersempit hasil & menghindari elemen yang mengganggu visimu"],answer:2,explain:"Batasan negatif sama pentingnya dengan deskripsi positif untuk mengarahkan keluaran.",hint:"Apa yang sering muncul di hasil AI yang tidak kamu inginkan?"},
{n:36,type:"mcq",micro:"Menyimpan proses",q:"Menyimpan instruksi & versi yang kamu pakai saat membuat karya AI berguna untuk...",options:["Bisa mengulang, menyesuaikan, & (bila diminta) menunjukkan proses & tingkat kontribusimu","Tidak ada gunanya","Hanya untuk pamer"],answer:0,explain:"Catatan proses membantu iterasi & transparansi tentang bagaimana karya dibuat.",hint:"Bagaimana kamu bisa membuat variasi yang mirip nanti kalau lupa instruksinya?"},
{n:37,type:"tf",micro:"Menyunting membuat karya lebih milikmu",q:"Benar atau Salah: Menyunting, menggabung, mengubah, & mengembangkan keluaran AI dengan pilihan & keterampilanmu sendiri tidak mengubah apa pun tentang seberapa 'milikmu' sebuah karya.",answer:false,explain:"Justru semakin banyak kontribusi kreatifmu (menyunting, menggabung, mengembangkan), semakin karya itu menjadi ekspresimu. Karya yang hanya keluaran AI mentah bukan ekspresi pribadi.",hint:"Apa yang mengubah 'hasil AI' menjadi 'karyaku'?"},
{n:38,type:"mcq",micro:"AI musik & audio",q:"AI yang menghasilkan musik atau suara...",options:["Tidak ada","Bisa membantu membuat latar, demo, atau ide melodi — dengan pertimbangan hak (meniru artis) & transparansi yang sama seperti teks & gambar","Selalu bebas dipakai untuk apa pun"],answer:1,explain:"Prinsip yang sama berlaku untuk semua media generatif: hak, atribusi, kejujuran, & pengembangan pribadi.",hint:"Apakah aturan untuk gambar AI juga berlaku untuk musik AI?"},
{n:39,type:"mcq",micro:"Menilai apakah pantas memakai AI",q:"Untuk sebuah tugas kreatif, apakah pantas memakai AI bergantung pada...",options:["Selalu pantas","Tidak pernah pantas","Tujuan tugas (menilai keterampilanmu? membuat produk?), aturan yang berlaku, & apakah kamu transparan tentang pemakaiannya"],answer:2,explain:"Konteks menentukan: latihan menggambar yang dinilai berbeda dari membuat poster acara. Aturan & transparansi juga penting.",hint:"Apakah tugas ini menilai kemampuanmu, atau butuh sebuah hasil?"},
{n:40,type:"open",micro:"Merancang proyek kreatif manusia+AI",q:"Kamu membuat komik pendek 4 halaman untuk majalah sekolah. Rencanakan pembagian kerja manusia–AI: (1) bagian mana yang kamu kerjakan sendiri & mengapa, (2) bagian mana AI membantu & bagaimana, (3) bagaimana kamu menjaga komik itu tetap ekspresimu, (4) bagaimana kamu bersikap jujur/transparan tentang pemakaian AI, (5) satu pertimbangan hak/etika.",sample:"(1) Aku kerjakan sendiri: cerita & dialog (ini inti ekspresiku & yang dinilai), tata panel/komposisi, & penintaan/pewarnaan akhir — supaya gaya visualnya konsisten & terasa milikku. (2) AI membantu: menghasilkan beberapa variasi konsep desain karakter & latar sebagai referensi awal (aku gambar ulang sendiri dengan gayaku); memberi masukan apakah alur cerita jelas & pacing-nya enak; membantu memeriksa ejaan dialog. (3) Menjaga tetap ekspresiku: semua gambar final kutinta & warnai sendiri; desain karakter kukembangkan dari referensi AI tapi kusesuaikan sampai khas; cerita & humor sepenuhnya dariku. (4) Transparansi: di halaman kredit kutulis 'Cerita & gambar oleh [nama]; referensi konsep awal dibantu AI.' (5) Etika/hak: aku tidak meminta AI meniru gaya komikus terkenal tertentu, & tidak memasukkan wajah orang nyata tanpa izin; aku juga memastikan referensi AI tidak mengandung logo/karakter berhak cipta yang ikut tersalin.",explain:"Rencana baik menjaga inti kreatif (cerita, gaya visual, eksekusi akhir) di tangan pembuat, memakai AI untuk referensi & umpan balik, transparan dalam kredit, & mempertimbangkan hak (tidak meniru komikus spesifik, izin wajah, hindari elemen berhak cipta).",hint:"Simpan yang 'inti & dinilai' untuk dirimu; pakai AI untuk referensi, umpan balik, & percepatan — lalu ungkapkan."},

// FASE C — PENERAPAN / JEMBATAN ABSTRAK (41-60): hak cipta, atribusi, kualitas, alur kerja
{n:41,type:"mcq",micro:"Hak cipta karya buatan AI",q:"Status hak cipta karya yang dihasilkan AI...",options:["Rumit & berbeda antar negara; di banyak tempat, karya tanpa cukup kontribusi kreatif manusia mungkin tidak dilindungi hak cipta sepenuhnya","Selalu jelas & sama di mana-mana","Selalu milik pengguna sepenuhnya"],answer:0,explain:"Aturan masih berkembang. Kontribusi kreatif manusia yang substansial umumnya penting untuk perlindungan & klaim kepemilikan.",hint:"Kalau kamu hanya mengetik satu kalimat & AI membuat segalanya, seberapa besar 'karyamu' di situ?"},
{n:42,type:"mcq",micro:"Data pelatihan & karya orang lain",q:"Perdebatan besar tentang AI generatif:",options:["Warna antarmuka terbaik","Apakah adil & sah model dilatih dari karya berhak cipta (buku, gambar, lagu) tanpa izin atau kompensasi pembuat aslinya","Apakah AI boleh menyala malam hari"],answer:1,explain:"Model belajar 'gaya' & pola dari karya manusia. Hak & kompensasi pembuat asli diperdebatkan secara hukum & etika.",hint:"Dari karya siapa model belajar meniru sebuah gaya?"},
{n:43,type:"mcq",micro:"Atribusi & kejujuran",q:"Praktik yang jujur saat membagikan karya yang dibantu AI:",options:["Selalu sembunyikan","Selalu klaim sepenuhnya buatan sendiri","Sebutkan peran AI sejelas yang relevan untuk konteksnya (mis. 'gambar dibuat dengan AI', 'draf dibantu AI, disunting oleh saya')"],answer:2,explain:"Tingkat & cara pengungkapan bergantung konteks, tapi menyesatkan orang tentang asal-usul karya tidak jujur.",hint:"Apa yang perlu diketahui orang yang melihat/memakai karyamu?"},
{n:44,type:"mcq",micro:"Kualitas: 'terlihat bagus' vs 'benar/bermakna'",q:"Keluaran AI bisa 'terlihat bagus' (rapi, lancar, estetis) tapi...",options:["Kurang akurat (teks), kurang bermakna/berjiwa (seni), atau generik — kualitas sejati butuh penilaian & pengembangan manusia","Selalu berkualitas tinggi","Selalu buruk"],answer:0,explain:"Kelancaran & estetika permukaan tidak sama dengan kebenaran, kedalaman, atau orisinalitas.",hint:"Apakah 'terlihat rapi' sama dengan 'benar & bermakna'?"},
{n:45,type:"mcq",micro:"Alur kerja: draf cepat, revisi lambat",q:"Pola alur kerja umum manusia+AI yang produktif:",options:["AI melakukan semuanya","AI menghasilkan draf/variasi dengan cepat; manusia menghabiskan waktu untuk memilih, memverifikasi, merevisi, & menambah nilai","Manusia membuat draf lambat; AI merevisi"],answer:1,explain:"AI mempercepat bagian 'menghasilkan banyak'; nilai manusia ada di 'memilih & menyempurnakan yang tepat'.",hint:"Bagian mana yang AI cepat, & bagian mana yang butuh penilaianmu?"},
{n:46,type:"mcq",micro:"Menghindari plagiarisme lewat AI",q:"Kalau AI menghasilkan teks yang ternyata sangat mirip dengan karya yang sudah ada (kebetulan atau karena data latih)...",options:["Bukan masalahmu, AI yang membuatnya","Boleh dipakai karena 'AI yang menulis'","Kamu tetap bertanggung jawab; periksa orisinalitas & tulis ulang dengan pemahaman & kata-katamu sendiri"],answer:2,explain:"Menyerahkan teks yang menjiplak karya lain adalah plagiarisme, terlepas dari apakah AI membantunya.",hint:"Kalau teks dari AI ternyata menjiplak, siapa yang menyerahkannya?"},
{n:47,type:"order",micro:"Alur kerja kreatif manusia+AI yang bertanggung jawab",q:"Urutkan langkah alur kerja membuat karya dengan AI secara bertanggung jawab.",items:["Perjelas visi & tujuanmu; putuskan bagian mana yang inti & harus kamu kerjakan","Pakai AI untuk mempercepat draf/variasi/riset di bagian pendukung","Pilih, verifikasi (fakta), sunting, & kembangkan dengan keterampilan & pilihanmu","Periksa hak & orisinalitas; ungkapkan pemakaian AI sesuai konteks; bagikan"],answer:[0,1,2,3],explain:"Visi & inti dulu → AI untuk bagian pendukung → kurasi, verifikasi, & pengembangan manusia → cek hak & transparansi → bagikan.",hint:"Kamu harus tahu apa yang 'inti' bagimu sebelum mendelegasikan yang lain."},
{n:48,type:"mcq",micro:"Nilai yang ditambahkan manusia",q:"Dalam karya manusia+AI, kontribusi manusia yang paling bernilai biasanya:",options:["Visi & tujuan, kurasi (memilih yang tepat), penyuntingan & penyempurnaan, verifikasi, konteks, & tanggung jawab","Hanya mengetik instruksi","Tidak ada, AI melakukan semuanya"],answer:0,explain:"AI menyediakan kapasitas produksi; manusia menyediakan arah, penilaian, makna, & pertanggungjawaban.",hint:"Apa yang tidak bisa didelegasikan ke AI?"},
{n:49,type:"mcq",micro:"Menandai konten sintetis",q:"Untuk gambar/video AI yang realistis & bisa disalahpahami sebagai nyata, menandainya sebagai buatan AI...",options:["Membuat karya jadi ilegal","Membantu mencegah penipuan & misinformasi — bagian dari tanggung jawab pembuat, meski label bisa dihapus orang lain","Tidak perlu"],answer:1,explain:"Pelabelan adalah pengaman terhadap penyalahgunaan; ia bagian dari solusi, bukan solusi tunggal.",hint:"Apa gunanya tahu 'ini dibuat AI' saat melihat gambar yang tampak seperti foto nyata?"},
{n:50,type:"mcq",micro:"Menggunakan AI dalam pekerjaan berbayar",q:"Kalau kamu dibayar untuk membuat sesuatu & memakai AI dalam prosesnya...",options:["Sembunyikan dari klien","Tidak perlu memikirkan hak","Bersikap transparan dengan klien tentang peran AI (sesuai kesepakatan), pastikan kamu punya hak memakai hasilnya, & tetap bertanggung jawab atas kualitas"],answer:2,explain:"Dalam pekerjaan profesional, kejujuran dengan klien & kepastian hak atas hasil adalah bagian dari integritas & profesionalisme.",hint:"Apa yang berhak diketahui klien tentang bagaimana pekerjaan mereka dibuat?"},
{n:51,type:"open",micro:"Menilai pemakaian AI dalam berbagai konteks kreatif",q:"Untuk tiap konteks, nilai apakah memakai AI generatif (a) sepenuhnya sesuai, (b) sesuai dengan pengungkapan/penyuntingan, atau (c) tidak sesuai — beri alasan: (1) membuat poster pengumuman acara kelas, (2) tugas seni yang menilai kemampuan menggambarmu, (3) menulis puisi untuk lomba yang menilai orisinalitas peserta, (4) membuat latar musik untuk video proyek kelompok.",sample:"(1) Poster acara: (a) sepenuhnya sesuai — tujuannya menghasilkan poster yang berfungsi, taruhan rendah, tidak ada yang menilai kemampuan senimu; tetap sunting agar cocok & periksa tidak ada elemen berhak cipta. (2) Tugas seni yang menilai kemampuan menggambar: (c) tidak sesuai untuk menghasilkan gambarnya — tujuannya menilai keterampilanmu; AI hanya boleh untuk referensi/belajar prinsip (& itu pun sesuai aturan guru). (3) Puisi lomba orisinalitas: (c) tidak sesuai — konteks menilai ekspresi & kemampuan peserta sendiri; menyerahkan puisi AI adalah menipu. (4) Latar musik video kelompok: (b) sesuai dengan pengungkapan — kalau tujuannya video yang bagus (bukan menilai kemampuan komposisi kalian), AI boleh membantu latar; sebutkan di kredit 'musik latar dibuat dengan AI', pastikan tidak meniru lagu berhak cipta, & sepakati dengan kelompok.",explain:"Jawaban baik membedakan konteks berdasarkan: apakah kemampuan pembuat yang dinilai, seberapa besar taruhannya, & apakah transparansi cukup untuk membuatnya jujur.",hint:"Kunci: apakah tugas/konteks itu menilai KEMAMPUANMU, atau butuh sebuah HASIL?"},
{n:52,type:"mcq",micro:"Menjaga keterampilan tetap tumbuh",q:"Kekhawatiran wajar tentang terlalu mengandalkan AI generatif:",options:["Kalau AI selalu mengerjakan bagian sulit, keterampilanmu (menulis, menggambar, menyusun argumen) bisa tidak berkembang — imbangi dengan tetap berlatih inti keterampilan itu","Tidak ada kekhawatiran","Keterampilan tumbuh otomatis"],answer:0,explain:"Keterampilan tumbuh dari usaha pada bagian yang menantang. Menyerahkan itu terus-menerus menghentikan pertumbuhan.",hint:"Apa yang terjadi pada otot yang tugas beratnya selalu diambil alih?"},
{n:53,type:"tf",micro:"Transparansi bergantung konteks",q:"Benar atau Salah: Seberapa detail kamu perlu mengungkapkan pemakaian AI bergantung pada konteks — lomba orisinalitas menuntut kejujuran penuh, sementara poster fungsional mungkin tidak perlu label eksplisit, tapi tidak boleh menyesatkan di konteks mana pun.",answer:true,explain:"Prinsipnya konsisten (jangan menyesatkan), tapi tuntutan pengungkapan bervariasi menurut apa yang orang harapkan & apa yang dinilai.",hint:"Apakah semua konteks menuntut tingkat pengungkapan yang sama?"},
{n:54,type:"mcq",micro:"AI & kolaborasi tim kreatif",q:"Dalam proyek kreatif kelompok, memakai AI secara sehat berarti...",options:["Melarang semua pemakaian AI","Sepakati bersama untuk apa AI dipakai, pastikan setiap anggota tetap berkontribusi kreatif & memahami hasilnya, & transparan dalam kredit","Satu orang memakai AI diam-diam untuk seluruh proyek"],answer:1,explain:"Kesepakatan tim menjaga kontribusi & pembelajaran semua anggota, serta kejujuran kolektif.",hint:"Bagaimana memastikan proyek tetap karya SEMUA anggota?"},
{n:55,type:"mcq",micro:"Menghadapi kritik 'itu cuma AI'",q:"Kalau karyamu yang dibantu AI dikritik 'itu bukan seni sungguhan', respons yang matang:",options:["Sembunyikan bahwa AI dipakai","Berhenti berkarya","Jelaskan kontribusi kreatifmu (visi, kurasi, penyuntingan, pengembangan) & bersikap terbuka tentang peran AI — nilai karya bisa didiskusikan, tapi kejujuran soal proses itu penting"],answer:2,explain:"Debat tentang 'apa itu seni' adalah wajar & sehat. Yang penting kamu jujur tentang proses & bisa menjelaskan kontribusimu.",hint:"Apa yang bisa kamu tunjukkan sebagai kontribusi kreatifmu sendiri?"},
{n:56,type:"mcq",micro:"AI untuk prototipe & eksplorasi",q:"Dalam desain (produk, ruang, grafis), AI generatif berguna untuk...",options:["Membuat banyak prototipe/konsep cepat untuk dieksplorasi & diuji — sebelum manusia menyempurnakan pilihan terbaik","Menghasilkan desain final yang langsung diproduksi tanpa tinjauan","Menggantikan seluruh proses desain"],answer:0,explain:"Kecepatan menghasilkan variasi membantu eksplorasi; penilaian, penyempurnaan, & tanggung jawab tetap pada desainer.",hint:"Untuk apa berguna 'membuat 20 konsep dalam satu jam'?"},
{n:57,type:"tf",micro:"Karya AI mentah jarang jadi karya terbaik",q:"Benar atau Salah: Karya yang paling menonjol & bermakna biasanya adalah keluaran AI pertama yang mentah, tanpa perlu pengembangan atau penyempurnaan manusia.",answer:false,explain:"Sebaliknya — AI menghasilkan keluaran 'rata-rata polanya'. Kedalaman, kekhasan, & makna datang dari pengembangan, kurasi, & penyempurnaan oleh manusia dengan visi yang jelas.",hint:"Apakah menyerahkan hasil AI pertama yang keluar menghasilkan karya yang khas?"},
{n:58,type:"mcq",micro:"Menilai apakah kamu 'penulis'-nya",q:"Uji sederhana apakah sebuah karya benar-benar 'karyamu':",options:["Apakah cepat dibuat?","Bisakah kamu menjelaskan setiap pilihan penting di dalamnya & kontribusi kreatifmu? Apakah ia mencerminkan visi & suaramu?","Apakah terlihat rapi?"],answer:1,explain:"Kepenulisan bukan soal siapa yang mengetik, tapi siapa yang membuat pilihan kreatif yang membentuk karya itu.",hint:"Kalau seseorang bertanya 'kenapa kamu memilih ini', apakah kamu punya jawaban?"},
{n:59,type:"mcq",micro:"AI & pekerja kreatif",q:"Dampak AI generatif pada pekerja kreatif (ilustrator, penulis, musisi) menimbulkan pertanyaan tentang...",options:["Tidak ada dampak","Semua pekerja kreatif akan hilang","Bagaimana nilai & penghidupan mereka terpengaruh, keadilan penggunaan karya mereka sebagai data latih, & bagaimana masyarakat menghargai kreativitas manusia"],answer:2,explain:"Perubahan teknologi pada industri kreatif menuntut perhatian pada keadilan, kompensasi, & transisi bagi pekerja.",hint:"Siapa yang karyanya dipakai melatih model, & bagaimana pendapatan mereka terpengaruh?"},
{n:60,type:"open",micro:"Kebijakan penggunaan AI untuk majalah sekolah",q:"Majalah sekolahmu menerima kiriman karya (tulisan, ilustrasi, foto). Buat kebijakan singkat (6+ poin) tentang penggunaan AI generatif dalam kiriman, mencakup: apa yang boleh & tidak, kewajiban pengungkapan, verifikasi konten faktual, hak (meniru gaya, wajah orang), & bagaimana karya dengan bantuan AI dikredit. Beri alasan tiap poin.",sample:"(1) Karya boleh dibantu AI untuk ide awal, referensi, riset, & penyuntingan bahasa — tapi kontribusi kreatif utama (tulisan, komposisi, konsep) harus dari pengirim; karya yang seluruhnya keluaran AI mentah tidak diterima sebagai 'karya' — karena majalah menghargai ekspresi & keterampilan siswa. (2) Setiap kiriman yang dibantu AI wajib menyebutkan bagaimana (mis. 'ilustrasi dikembangkan dari referensi AI', 'draf dibantu AI, ditulis ulang oleh penulis') — transparansi mencegah menyesatkan pembaca. (3) Semua fakta, angka, kutipan, & nama dalam tulisan diverifikasi oleh penulis & redaksi ke sumber tepercaya — AI bisa mengarang, & majalah bertanggung jawab atas akurasi. (4) Tidak menerima karya yang meniru gaya khas seniman/penulis tertentu yang dapat dikenali, atau yang menampilkan wajah/nama orang nyata tanpa izin — menghormati hak & martabat orang lain. (5) Gambar AI yang realistis diberi keterangan 'ilustrasi AI' agar tidak disalahartikan sebagai foto — mencegah misinformasi. (6) Kredit ditulis jujur: nama pengirim sebagai pembuat, dengan catatan peran AI bila ada — pembaca berhak tahu. (7) Redaksi berhak menolak karya yang pengungkapannya tidak jujur atau yang melanggar poin di atas.",explain:"Kebijakan baik menuntut kontribusi kreatif manusia yang substansial, pengungkapan yang jelas, verifikasi fakta, penghormatan hak (gaya seniman, citra orang), pelabelan konten realistis, & kredit yang jujur — dengan alasan tiap poin.",hint:"Tiap poin bersandar pada satu nilai: menghargai keterampilan siswa, transparansi, akurasi, hak orang lain, atau anti-misinformasi."},

// FASE D — PENALARAN (61-80): dilema, batas, dampak
{n:61,type:"mcq",micro:"Orisinalitas & 'ide dari AI'",q:"Kalau ide inti sebuah karya datang dari saran AI, & kamu hanya mengeksekusinya...",options:["Kontribusi kreatifmu lebih terbatas; untuk karya yang menilai orisinalitas, sebaiknya ide inti datang darimu & AI membantu di bagian lain","Tidak masalah, ide dari mana pun sama saja","Karya itu otomatis milik AI"],answer:0,explain:"Di konteks yang menghargai orisinalitas, dari mana ide inti berasal itu penting. AI paling aman membantu eksekusi & bagian pendukung.",hint:"Kalau seluruh 'apa'-nya dari AI & kamu hanya mengerjakan 'bagaimana', seberapa orisinal karya itu?"},
{n:62,type:"tf",micro:"Meniru gaya hidup vs gaya umum",q:"Benar atau Salah: Ada perbedaan etis antara meminta AI membuat karya dalam 'gaya umum' (cat air, minimalis, komik) & meniru 'gaya khas seniman tertentu yang dapat dikenali' — yang kedua lebih bermasalah.",answer:true,explain:"Gaya umum adalah bahasa visual bersama; gaya khas seseorang adalah bagian dari identitas & penghidupan mereka.",hint:"Apakah 'gaya cat air' & 'gaya persis pelukis X' menimbulkan masalah yang sama?"},
{n:63,type:"mcq",micro:"Menyikapi konten AI yang menyesatkan orang lain",q:"Kamu melihat teman menyebarkan 'foto' peristiwa yang jelas dibuat AI seolah nyata. Tindakan yang bertanggung jawab:",options:["Diam saja","Beri tahu dengan sopan bahwa itu kemungkinan buatan AI & mengapa; sarankan mencari sumber tepercaya sebelum menyebar lagi","Ikut menyebarkan"],answer:1,explain:"Membantu orang mengenali konten sintetis & memverifikasi mengurangi penyebaran misinformasi.",hint:"Apa yang bisa kamu lakukan saat melihat orang tertipu konten AI?"},
{n:64,type:"mcq",micro:"Nilai kreativitas manusia",q:"Meski AI bisa menghasilkan karya yang mengesankan, kreativitas manusia tetap bernilai khas karena...",options:["AI selalu menghasilkan karya buruk","Tidak ada bedanya","Berakar pada pengalaman hidup, emosi, konteks budaya, maksud, & hubungan dengan penonton — hal yang AI tidak miliki"],answer:2,explain:"Karya manusia membawa niat, cerita, & kerentanan yang berasal dari kehidupan nyata. Itu sumber makna yang berbeda.",hint:"Apa yang seorang seniman bawa ke karyanya yang tidak dimiliki program?"},
{n:65,type:"tf",micro:"AI generatif menurunkan hambatan, bukan menghapus kebutuhan keterampilan",q:"Benar atau Salah: Karena AI generatif menurunkan hambatan teknis, keterampilan menilai kualitas, membuat pilihan kreatif, & menyempurnakan menjadi tidak lagi dibutuhkan.",answer:false,explain:"Hambatan teknis memang turun, tapi keterampilan menilai kualitas, membuat pilihan kreatif, & menyempurnakan tetap dibutuhkan — & justru makin membedakan saat semua orang bisa menghasilkan output cepat.",hint:"Kalau semua orang bisa menghasilkan 100 gambar, siapa yang menonjol?"},
{n:66,type:"mcq",micro:"Ketergantungan yang mengikis",q:"Selalu memakai AI untuk 'mengatasi bagian sulit' (menyusun kalimat yang bagus, menggambar tangan, membangun harmoni) berisiko...",options:["Bagian sulit itu tidak pernah kamu kuasai; padahal justru di situ pertumbuhan & kepuasan berkarya sering berada","Tidak ada risiko","Kamu jadi ahli otomatis"],answer:0,explain:"Menghindari kesulitan terus-menerus berarti keterampilan itu stagnan. Sebagian nilai berkarya ada pada menaklukkan yang sulit.",hint:"Apa yang kamu lewatkan kalau AI selalu mengerjakan bagian yang menantang?"},
{n:67,type:"mcq",micro:"AI & keaslian pengalaman",q:"Sebuah esai reflektif tentang pengalaman pribadimu yang sebagian besar ditulis AI...",options:["Lebih baik karena lebih rapi","Kehilangan inti-nya — refleksi pribadi bergantung pada suara, ingatan, & kejujuranmu sendiri; AI hanya bisa 'mengarang' pengalaman yang tampak masuk akal","Sama saja bagusnya"],answer:1,explain:"Untuk karya yang nilainya terletak pada keaslian pengalaman & suara pribadi, AI tidak bisa menggantikan yang dibutuhkan.",hint:"Bisakah AI benar-benar tahu bagaimana rasanya pengalamanmu?"},
{n:68,type:"tf",micro:"Transparansi membangun kepercayaan jangka panjang",q:"Benar atau Salah: Kreator yang jujur & konsisten tentang bagaimana mereka memakai AI cenderung membangun kepercayaan penonton yang lebih tahan lama daripada yang menyembunyikannya & kemudian ketahuan.",answer:true,explain:"Kepercayaan sulit dibangun & mudah runtuh. Kejujuran sejak awal melindungi hubungan dengan penonton.",hint:"Apa yang terjadi pada kepercayaan penonton saat mereka menemukan sesuatu disembunyikan?"},
{n:69,type:"mcq",micro:"Menilai klaim 'dibuat sepenuhnya oleh AI'",q:"Sebuah karya dipromosikan 'dibuat 100% oleh AI, tanpa campur tangan manusia'. Kenyataannya biasanya...",options:["Benar-benar tanpa manusia","Tidak mungkin ada karya AI","Selalu ada campur tangan manusia: memilih model, menulis instruksi, memilih di antara hasil, sering menyunting — klaim '0% manusia' hampir selalu berlebihan"],answer:2,explain:"Bahkan karya 'AI' melibatkan pilihan manusia. Klaim ekstrem sering pemasaran.",hint:"Siapa yang menulis instruksinya & memilih mana yang dipublikasikan?"},
{n:70,type:"order",micro:"Menangani karya yang tidak sengaja menjiplak",q:"Kamu sadar gambar/teks AI yang kamu pakai sangat mirip karya yang sudah ada. Urutkan respons.",items:["Berhenti memakainya untuk sementara & bandingkan dengan karya asli yang mirip itu","Kalau kemiripannya substansial, jangan pakai — buat versi yang benar-benar berbeda dengan kontribusimu sendiri","Kalau sudah terlanjur dibagikan, akui, tarik, & perbaiki","Ke depan, periksa orisinalitas keluaran AI sebelum memakainya untuk hal publik"],answer:[0,1,2,3],explain:"Berhenti & bandingkan → jangan pakai bila mirip substansial → perbaiki bila terlanjur → cegah ke depan.",hint:"Tanggung jawab tetap padamu meski AI yang menghasilkannya."},
{n:71,type:"mcq",micro:"Memakai AI untuk parodi/kritik",q:"Memakai AI membuat gambar satir tokoh publik untuk kritik sosial...",options:["Bisa dibenarkan sebagai ekspresi/kritik, tapi tetap ada batas: tidak memfitnah, tidak menyesatkan sebagai nyata, & mempertimbangkan dampak & konteks","Selalu boleh tanpa batas","Selalu dilarang"],answer:0,explain:"Kritik & satir punya ruang, tapi konten sintetis tentang orang nyata tetap menuntut kehati-hatian terhadap fitnah & penyesatan.",hint:"Apa bedanya satir yang jelas & 'video palsu yang tampak nyata'?"},
{n:72,type:"tf",micro:"Kreativitas manusia+AI adalah keterampilan baru",q:"Benar atau Salah: Memakai AI generatif dengan baik dalam berkarya adalah keterampilan tersendiri — mengarahkan, mengevaluasi, mengurasi, & mengintegrasikan keluaran AI ke dalam visi yang koheren.",answer:true,explain:"Seperti belajar alat baru mana pun, ada keterampilan dalam memakai AI secara kreatif & bertanggung jawab — & ia dibangun di atas selera & keterampilan dasar.",hint:"Apakah 'mengarahkan & mengurasi AI menuju visi yang jelas' butuh keterampilan?"},
{n:73,type:"mcq",micro:"Menyeimbangkan efisiensi & pembelajaran",q:"Untuk keterampilan yang sedang kamu bangun, pola memakai AI generatif yang sehat seiring waktu:",options:["Makin lama makin bergantung","Awalnya lebih banyak bantuan (belajar prinsip, melihat contoh), lalu kurangi ketergantungan seiring kamu mahir — sampai bisa berkarya baik tanpa AI di keterampilan inti itu","Ketergantungan yang sama besar selamanya"],answer:1,explain:"Bantuan yang baik seperti roda bantu sepeda: banyak di awal, dilepas saat kamu bisa sendiri.",hint:"Kapan roda bantu sepeda seharusnya dilepas?"},
{n:74,type:"mcq",micro:"AI & keragaman budaya dalam karya",q:"Model generatif dilatih terutama dari data yang berat ke budaya/bahasa tertentu. Untuk kreator dari budaya yang kurang terwakili, ini berarti...",options:["Tidak ada dampak","AI mewakili semua budaya sama baiknya","Keluaran AI bisa kurang cocok atau menstereotipkan budaya mereka; kontribusi & pengetahuan kreator sendiri jadi lebih penting untuk mengoreksi & memperkaya"],answer:2,explain:"Bias data latih muncul dalam keluaran kreatif. Kreator yang mengenal konteksnya bisa mengoreksi & membawa keaslian.",hint:"Kalau AI jarang 'melihat' budayamu, seberapa baik ia menggambarkannya?"},
{n:75,type:"mcq",micro:"Menilai apakah sebuah pemakaian 'curang'",q:"Cara menilai apakah memakai AI dalam sebuah tugas kreatif adalah kecurangan:",options:["Tanyakan: apa yang tugas ini nilai/latih? apakah AI mengerjakan bagian itu? apakah aku transparan? apakah aku melanggar aturan yang berlaku?","Kalau tidak ketahuan, tidak curang","Semua pemakaian AI adalah curang"],answer:0,explain:"Kecurangan adalah soal apakah kamu menghindari yang seharusnya kamu kerjakan & pelajari, & apakah kamu jujur — bukan soal ketahuan.",hint:"Apa inti yang dinilai/dilatih tugas ini, & siapa yang mengerjakannya?"},
{n:76,type:"tf",micro:"Pembuat bertanggung jawab atas dampak",q:"Benar atau Salah: Kalau karya AI yang kamu buat & bagikan ternyata menyesatkan atau melanggar hak orang, 'AI yang membuatnya' adalah pembelaan yang sah & membebaskanmu dari tanggung jawab.",answer:false,explain:"Alat tidak bertanggung jawab. Keputusan untuk membuat & menyebarkan sebuah karya adalah keputusan manusia, jadi 'AI yang membuatnya' bukan pembelaan.",hint:"Kalau AI membantumu membuat kabar palsu & kamu menyebarnya, siapa yang bertanggung jawab?"},
{n:77,type:"mcq",micro:"Menghargai proses vs hanya hasil",q:"Sebagian nilai berkarya (kepuasan, pembelajaran, ekspresi) terletak pada PROSESnya. Menyerahkan seluruh proses ke AI...",options:["Selalu pilihan terbaik","Bisa memberi hasil, tapi menghilangkan sebagian besar yang membuat berkarya bermakna & membangun bagi si pembuat","Tidak menghilangkan apa pun"],answer:1,explain:"Kalau tujuanmu adalah tumbuh, mengekspresikan diri, atau menikmati proses — mendelegasikan semuanya mengalahkan tujuan itu.",hint:"Mengapa orang menikmati memasak sendiri, bukan hanya membeli makanan jadi?"},
{n:78,type:"mcq",micro:"Menyikapi masa depan yang berubah cepat",q:"Karena alat AI generatif berubah cepat, sikap yang tahan lama bagi kreator:",options:["Hafalkan trik untuk satu alat tertentu","Tunggu sampai teknologinya 'selesai'","Pegang prinsipnya (visi & kontribusi manusia sebagai inti, verifikasi, hormati hak, transparan, jaga keterampilan) — prinsip ini bertahan meski alatnya berganti"],answer:2,explain:"Trik spesifik cepat usang; prinsip berkarya yang bertanggung jawab bertahan lintas alat.",hint:"Apa yang tetap penting meski alatnya berganti tiap tahun?"},
{n:79,type:"mcq",micro:"Nilai 'buatan tangan' & 'buatan manusia'",q:"Munculnya AI generatif membuat sebagian orang lebih menghargai karya yang jelas buatan manusia. Ini menunjukkan...",options:["Nilai sebuah karya juga terletak pada makna 'seseorang membuat ini', hubungan, & keterampilan yang terlihat — bukan hanya hasil visualnya","Karya AI selalu lebih rendah","Tidak ada yang menghargai karya manusia lagi"],answer:0,explain:"Sebagaimana barang buatan tangan punya nilai khas di era produksi massal, karya buatan manusia bisa punya nilai khas di era AI.",hint:"Mengapa orang membayar lebih untuk barang 'buatan tangan'?"},
{n:80,type:"open",micro:"Menganalisis dilema kreatif AI",q:"Seorang siswa memenangkan lomba desain poster sekolah. Belakangan diketahui poster itu dibuat hampir seluruhnya oleh AI dari satu instruksi, tanpa penyuntingan berarti, & tanpa pengungkapan. Analisis: (1) apa yang bermasalah, (2) apakah 'aturan lomba tidak menyebut AI' menjadi pembenaran, (3) bagaimana seharusnya siswa itu memakai AI kalau memang ingin, (4) apa yang sebaiknya dilakukan panitia, (5) pelajaran umum.",sample:"(1) Bermasalah: lomba desain menilai kemampuan & kreativitas peserta; poster yang hampir seluruhnya keluaran AI mentah tidak mencerminkan kontribusi kreatif siswa itu; & tidak diungkapkannya pemakaian AI membuat panitia & peserta lain menilai berdasarkan asumsi yang salah (bahwa itu karya siswa). (2) 'Aturan tidak menyebut AI' bukan pembenaran penuh — ketiadaan aturan eksplisit tidak menghapus norma umum bahwa lomba kreativitas menilai karya peserta sendiri, & tidak menghapus kewajiban tidak menyesatkan. Siswa yang jujur akan bertanya ke panitia bila ragu. (3) Kalau ingin memakai AI: pakai untuk eksplorasi konsep awal & referensi, lalu kerjakan desain finalnya sendiri (tata letak, tipografi, olahan visual) dengan keterampilannya, & sertakan catatan 'konsep awal dibantu AI, desain final oleh saya' saat mengumpulkan. (4) Panitia sebaiknya: menetapkan aturan AI yang jelas untuk lomba berikutnya (boleh untuk apa, wajib diungkapkan); untuk kasus ini, menerapkan aturan yang paling adil sesuai kebijakan yang ada & prinsip 'menilai karya peserta' — mungkin meninjau ulang pemenang; & memakai kejadian ini untuk mendidik, bukan sekadar menghukum. (5) Pelajaran: di ranah kreatif, jujurlah tentang peran AI; ketiadaan aturan bukan izin; & nilai sebuah karya lomba terletak pada kontribusi kreatif orangnya.",explain:"Jawaban baik mengenali bahwa lomba menilai kemampuan peserta, bahwa tidak-diungkapkannya AI menyesatkan penilaian, bahwa ketiadaan aturan eksplisit tidak menghapus norma & kewajiban tidak menyesatkan, & mengusulkan pemakaian AI yang sah (konsep + eksekusi sendiri + pengungkapan) serta respons panitia yang mendidik + memperjelas aturan.",hint:"Tanyakan: apa yang lomba ini nilai? apakah pemenang benar-benar melakukannya? apakah penilaian dibuat atas informasi yang jujur?"},

// FASE E — TANTANGAN (81-100): sintesis, kapstone
{n:81,type:"mcq",micro:"Model kolaborasi manusia+AI yang sehat",q:"Model yang paling menjaga nilai & tanggung jawab dalam berkarya dengan AI:",options:["Tidak ada kolaborasi, salah satu saja","Manusia memegang visi, membuat pilihan kreatif kunci, memverifikasi, menyempurnakan, & bertanggung jawab; AI mempercepat produksi bahan & memberi umpan balik","AI memegang visi & membuat karya; manusia menyetujui"],answer:1,explain:"Pembagian yang menjaga makna & akuntabilitas: arah & penilaian manusia, kapasitas produksi AI.",hint:"Siapa yang memegang visi & bertanggung jawab, siapa yang mempercepat?"},
{n:82,type:"mcq",micro:"Membuat pernyataan proses (artist statement)",q:"Menyertakan pernyataan singkat tentang bagaimana kamu memakai AI dalam sebuah karya...",options:["Membuat karya terlihat lemah","Tidak pernah perlu","Membantu penonton memahami & menghargai kontribusimu, & membangun kepercayaan — praktik yang makin umum & dihargai"],answer:2,explain:"Transparansi proses menjadi bagian dari praktik kreatif yang bertanggung jawab di era AI.",hint:"Apa yang membantu orang menghargai kontribusimu dengan tepat?"},
{n:83,type:"tf",micro:"Kejujuran soal proses tidak mengurangi nilai karya",q:"Benar atau Salah: Begitu kamu mengakui bahwa AI membantu sebagian proses, karyamu otomatis menjadi 'tidak berharga' & kontribusimu tidak lagi layak dinilai.",answer:false,explain:"Bersikap jujur tentang bantuan AI tidak otomatis membuat karya kurang berharga — kontribusi kreatif, penyempurnaan, & maksud kamu tetap dinilai. Yang merusak nilai (kepercayaan) adalah menyembunyikan proses & ketahuan.",hint:"Apa yang lebih merusak nilai: mengakui bantuan AI, atau ketahuan menyembunyikannya?"},
{n:84,type:"mcq",micro:"Menjaga keterampilan inti di era AI",q:"Strategi bagi pelajar kreatif agar tetap berkembang meski AI tersedia:",options:["Tetapkan keterampilan inti yang ingin kamu kuasai & latih itu sendiri secara rutin; pakai AI untuk bagian pendukung, eksplorasi, & umpan balik — bukan untuk menggantikan latihan inti","Serahkan semua ke AI & fokus pada 'mengarahkan' saja","Hindari AI sepenuhnya"],answer:0,explain:"Menjaga latihan pada keterampilan inti (menggambar, menulis, menyusun musik) sambil memanfaatkan AI di sekitarnya adalah keseimbangan yang menjaga pertumbuhan.",hint:"Bagian mana yang harus tetap kamu latih sendiri, & bagian mana AI boleh membantu?"},
{n:85,type:"order",micro:"Alur kreatif manusia+AI dari nol sampai bagikan",q:"Urutkan langkah membuat karya (mis. cerpen berilustrasi) dengan AI secara bertanggung jawab.",items:["Tetapkan visi, tema, & bagian inti yang kamu kerjakan sendiri (mis. cerita & suara)","Pakai AI untuk mempercepat bagian pendukung (referensi visual, variasi konsep, cek bahasa) & untuk umpan balik","Kurasi, verifikasi fakta bila ada, sunting, & kembangkan dengan keterampilan & pilihanmu","Periksa hak (gaya, citra orang, elemen berhak cipta) & orisinalitas; siapkan pengungkapan/kredit; bagikan"],answer:[0,1,2,3],explain:"Visi & inti → AI untuk pendukung & umpan balik → kurasi, verifikasi, & pengembangan manusia → cek hak & transparansi → bagikan.",hint:"Tentukan dulu apa yang tidak akan kamu delegasikan."},
{n:86,type:"mcq",micro:"Menilai alat AI generatif baru",q:"Sebelum memakai alat AI generatif baru untuk karya yang akan kamu bagikan, hal yang perlu dicek:",options:["Tidak perlu cek apa pun","Ketentuan penggunaannya (apakah kamu punya hak atas keluaran & boleh memakainya untuk tujuanmu), kebijakan data (apa yang terjadi pada yang kamu unggah), & reputasinya soal hak cipta","Hanya seberapa bagus hasilnya"],answer:1,explain:"Hak atas keluaran & kebijakan data bervariasi antar alat. Mengeceknya melindungi kamu & orang lain.",hint:"Apakah kamu benar-benar boleh memakai & membagikan apa yang alat ini hasilkan?"},
{n:87,type:"mcq",micro:"AI & suara kolektif kreator",q:"Kreator yang khawatir karyanya dipakai melatih AI tanpa izin bisa...",options:["Tidak bisa berbuat apa-apa","Berhenti berkarya","Bergabung dengan gerakan kreator lain, memakai opsi 'tolak pelatihan' bila tersedia, mendukung aturan yang lebih adil, & bersuara — perubahan sering datang dari tekanan kolektif"],answer:2,explain:"Kebijakan tentang data pelatihan & kompensasi masih berkembang; suara kolektif kreator adalah pendorong penting.",hint:"Apa yang bisa dilakukan banyak kreator bersama-sama?"},
{n:88,type:"tf",micro:"Kreativitas manusia tidak digantikan, tapi konteksnya berubah",q:"Benar atau Salah: AI generatif mengubah cara sebagian karya dibuat & apa yang membedakan kreator, tapi kebutuhan akan visi manusia, makna, penilaian, tanggung jawab, & keaslian pengalaman tidak hilang.",answer:true,explain:"Alat berubah; peran inti manusia dalam mengarahkan, memberi makna, & bertanggung jawab tetap.",hint:"Apa yang tetap dibutuhkan dari manusia meski produksi jadi lebih cepat?"},
{n:89,type:"mcq",micro:"Menghadapi tekanan 'semua pakai AI'",q:"Kalau kamu memilih membuat sesuatu tanpa AI (atau dengan AI minimal) untuk alasan pembelajaran atau nilai pribadi, & orang bilang 'kamu ketinggalan zaman'...",options:["Itu pilihan yang sah — nilai proses, pembelajaran, & keaslian adalah alasan yang valid; kamu tidak wajib memakai setiap alat","Kamu harus memakai AI karena semua begitu","Pilihanmu pasti salah"],answer:0,explain:"Bagaimana & seberapa banyak memakai AI dalam berkarya adalah pilihan pribadi yang bisa berbeda menurut tujuan & nilai masing-masing.",hint:"Apakah kamu wajib memakai setiap alat yang tersedia?"},
{n:90,type:"mcq",micro:"Menutup: membuat dengan AI",q:"Sikap paling berguna terhadap AI generatif dalam berkarya:",options:["Tolak AI karena mengancam kreativitas","Manfaatkan untuk mempercepat, mengeksplorasi, & mendapat umpan balik — sambil memegang visi & kontribusi kreatif sebagai milikmu, memverifikasi, menghormati hak orang lain, bersikap transparan, & menjaga keterampilan intimu tetap tumbuh","Serahkan semua karya ke AI"],answer:1,explain:"AI generatif adalah alat yang kuat bila dipakai dengan visi, tanggung jawab, kejujuran, & komitmen pada pertumbuhan diri.",hint:"Alat untuk memperluas kreativitasmu, atau menggantikannya?"},
{n:91,type:"mcq",micro:"Ringkasan: membuat dengan AI generatif",q:"Rangkuman paling tepat:",options:["AI generatif membuat karya sempurna yang langsung dipakai","AI generatif tidak berguna untuk berkarya","AI generatif menghasilkan konten baru dengan memprediksi pola dari karya manusia; ia berguna untuk draf, variasi, eksplorasi, & umpan balik, tapi keluarannya perlu diverifikasi (fakta) & dikembangkan; nilai & kepenulisan datang dari visi, kurasi, penyuntingan, & pilihan manusia; kamu bertanggung jawab atas dampak & kejujuran; hormati hak orang lain (gaya seniman, citra, hak cipta); bersikap transparan sesuai konteks; & jaga keterampilan intimu tetap berlatih"],answer:2,explain:"Inti: AI mempercepat produksi; manusia memberi visi, makna, penilaian, verifikasi, & tanggung jawab; hormati hak & bersikap jujur; jaga keterampilan.",hint:"Gabungkan: AI untuk bahan & percepatan + visi & kurasi manusia + verifikasi + hormati hak + transparan + jaga keterampilan."},
{n:92,type:"tf",micro:"Cara memakai AI dalam berkarya adalah pilihan yang bertanggung jawab",q:"Benar atau Salah: Karena AI-lah alat yang menghasilkan, cara seseorang memakainya dalam berkarya — jujur atau menyesatkan, menghormati hak atau melanggarnya — bukan tanggung jawab orang itu melainkan tanggung jawab alatnya.",answer:false,explain:"Alat tidak memilih bagaimana ia dipakai. Bagaimana seseorang memakai AI dalam berkarya adalah pilihan & tanggung jawabnya — integritas kreatif adalah cerminan pilihan pembuatnya.",hint:"Kalau seseorang memakai alat untuk menyesatkan orang, salah alatnya atau orangnya?"},
{n:93,type:"mcq",micro:"Tiga prinsip praktis",q:"Tiga prinsip praktis membuat dengan AI generatif:",options:["Pegang visi & kontribusi kreatifmu sebagai inti (& verifikasi fakta); hormati hak & citra orang lain & bersikap transparan; & jaga keterampilan intimu tetap berlatih","Serahkan semua ke AI; klaim sepenuhnya milikmu; jangan pernah berlatih sendiri","Hindari AI; jangan pernah bereksperimen"],answer:0,explain:"Visi & kontribusi (+ verifikasi) + hormati hak & transparansi + jaga keterampilan = inti berkarya dengan AI secara bertanggung jawab.",hint:"Gabungkan: visi & kontribusi + hormati hak & transparan + jaga keterampilan."},
{n:94,type:"open",micro:"Kapstone: proyek kreatif manusia+AI",q:"Rancang sebuah proyek kreatif nyata (cerpen berilustrasi, video pendek, komposisi musik, kampanye poster, dll.) yang memakai AI secara bertanggung jawab. Tuliskan: (1) visi & pesan proyek, (2) keterampilan inti yang ingin kamu latih & kerjakan sendiri, (3) bagian mana AI membantu & bagaimana (instruksi contoh), (4) rencana verifikasi (bila ada konten faktual), (5) pertimbangan hak (gaya, citra orang, hak cipta), (6) rencana transparansi/kredit, (7) bagaimana kamu menilai di akhir apakah karya itu 'milikmu' & apakah keterampilanmu bertumbuh.",sample:"Jawaban lengkap mengisi ketujuh bagian secara konkret. Contoh — video pendek 2 menit tentang pentingnya menjaga sungai di lingkungan. (1) Visi: menggugah warga muda untuk peduli & bertindak; nada penuh harapan, bukan menyalahkan. (2) Keterampilan yang kulatih sendiri: menulis naskah & narasi, menyunting video (pemotongan, ritme), pengambilan gambar sungai asli di lingkunganku. (3) AI membantu: menghasilkan beberapa variasi struktur naskah sebagai bahan awal ('Buat 3 kerangka video 2 menit yang mengajak warga muda peduli sungai, nada penuh harapan, tanpa menyalahkan'); membuat musik latar instrumental ('musik latar lembut penuh harapan, ~2 menit, instrumental, tanpa vokal, tidak meniru lagu tertentu'); memeriksa kejelasan & tata bahasa naskahku. (4) Verifikasi: setiap fakta tentang sungai (panjang, kondisi, data pencemaran) kucek ke data dinas lingkungan/sumber tepercaya sebelum masuk narasi. (5) Hak: musik AI kupastikan tidak meniru lagu berhak cipta; tidak menampilkan wajah warga tanpa izin; footage sungai adalah rekamanku sendiri. (6) Transparansi: di akhir video kutulis 'Naskah, pengambilan gambar, & penyuntingan oleh [nama]. Musik latar & bantuan kerangka awal dibuat dengan AI.' (7) Penilaian akhir: aku bisa menjelaskan setiap pilihan penting (mengapa urutan begini, mengapa nada begitu); karya mencerminkan pesan & suaraku; & aku merasa keterampilan menulis naskah & menyunting videoku meningkat dibanding proyek sebelumnya. Kalau ternyata AI mengerjakan terlalu banyak bagian inti, aku akan mengerjakan ulang bagian itu sendiri.",explain:"Kapstone menuntut penerapan menyeluruh: visi yang jelas, keterampilan inti yang dilatih sendiri, pemakaian AI di bagian pendukung dengan instruksi konkret, verifikasi fakta, pertimbangan hak (musik, citra, hak cipta), transparansi/kredit, & refleksi kepenulisan + pertumbuhan.",hint:"Bagian tersulit sering (2) & (7) — jujur pada dirimu tentang keterampilan mana yang harus tetap kamu kerjakan sendiri, & apakah karyanya benar-benar milikmu."},
{n:95,type:"mcq",micro:"Menilai kritik terhadap seni AI secara adil",q:"Debat 'apakah karya AI adalah seni sungguhan' paling produktif bila...",options:["Menganggap semua kritik tidak berdasar","Fokus pada pertanyaan konkret: berapa besar kontribusi kreatif manusia, apakah pembuatnya jujur tentang proses, & apakah karya itu bermakna bagi pembuat & penonton — bukan slogan","Menganggap semua seni AI tidak sah"],answer:1,explain:"Pertanyaan yang tepat bukan 'AI atau bukan' secara biner, melainkan tentang kontribusi, kejujuran, & makna.",hint:"Apa pertanyaan yang lebih berguna daripada 'ini seni sungguhan atau bukan'?"},
{n:96,type:"mcq",micro:"Menjaga integritas seiring alat berkembang",q:"Seiring AI generatif makin mampu, godaan untuk mendelegasikan lebih banyak akan meningkat. Yang menjaga integritas kreatifmu:",options:["Selalu memakai kemampuan terbaru semaksimal mungkin","Tidak ada yang bisa menjaganya","Kejelasan tentang tujuanmu (tumbuh? mengekspresikan diri? menghasilkan produk?) & komitmen pada kejujuran & kontribusi nyata — bukan aturan alat yang berubah-ubah"],answer:2,explain:"Prinsip internal (tujuan, kejujuran, kontribusi) lebih tahan lama daripada mengikuti kemampuan alat yang terus bertambah.",hint:"Apa yang tetap membimbingmu meski alatnya bisa melakukan lebih banyak tiap tahun?"},
{n:97,type:"tf",micro:"Membuat dengan AI adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Memakai AI generatif dengan baik — mengarahkan dengan instruksi yang jelas, mengurasi & mengevaluasi keluaran, mengintegrasikannya ke visi yang koheren, & melakukannya secara jujur & menghormati hak — adalah keterampilan yang berkembang dengan latihan.",answer:true,explain:"Seperti alat kreatif mana pun, ada keahlian dalam memakai AI generatif secara efektif & bertanggung jawab, & ia dibangun di atas selera & keterampilan dasar.",hint:"Apakah 'mengarahkan & mengurasi AI menuju visi yang jelas' membaik dengan latihan?"},
{n:98,type:"mcq",micro:"Inti yang dibawa pulang",q:"Satu gagasan inti tentang membuat dengan AI:",options:["AI bisa memperluas apa yang mungkin kamu buat, tapi visi, makna, penilaian, kejujuran, & tanggung jawab tetap milik & tugas manusia — & keterampilan intimu tetap layak dilatih","AI membuat kreativitas manusia tidak perlu lagi","AI generatif harus dihindari sepenuhnya"],answer:0,explain:"AI sebagai penguat kreativitas manusia yang dipakai dengan visi, kejujuran, & tanggung jawab — bukan pengganti.",hint:"Alat untuk memperluas kreativitasmu, dengan apa yang tetap menjadi tugasmu?"},
{n:99,type:"mcq",micro:"Prinsip transparansi",q:"Aturan sederhana tentang mengungkapkan pemakaian AI dalam karya:",options:["Selalu tulis paragraf panjang tentang AI di setiap karya","Jangan menyesatkan orang tentang bagaimana karya dibuat atau apakah sesuatu nyata; sesuaikan detail pengungkapan dengan konteks & apa yang orang harapkan","Selalu sembunyikan agar terlihat lebih hebat"],answer:1,explain:"Prinsipnya konsisten (tidak menyesatkan); bentuknya bervariasi menurut konteks (lomba, poster, artikel, seni realistis).",hint:"Apa yang orang harapkan tentang karya ini, & apakah kamu membiarkan mereka salah paham?"},
{n:100,type:"open",micro:"Kapstone: panduan 'Berkarya dengan AI' untuk teman sebaya",q:"Tulis panduan (8–10 poin) berjudul 'Berkarya dengan AI Generatif: Untuk Kita' untuk teman sebayamu. Cakup: apa itu AI generatif & cara ia menghasilkan, membuat instruksi yang baik, bahwa hasil perlu disunting & fakta perlu diverifikasi, menjaga visi & kontribusi sebagai milikmu, kejujuran & aturan lomba/tugas, menghormati hak (gaya seniman, wajah orang, hak cipta), menandai konten realistis, menjaga keterampilan inti tetap berlatih, & bahwa kamu bertanggung jawab atas dampaknya. Gunakan bahasa jelas & contoh konkret.",sample:"Contoh panduan: 1) AI generatif membuat teks/gambar/musik BARU dengan menebak pola dari jutaan karya manusia — hasilnya belum ada persis di mana pun, tapi 'gayanya' dipelajari dari orang. 2) Instruksi yang baik itu spesifik: subjek, suasana, gaya, warna, format, & apa yang TIDAK kamu mau ('gambar rubah di hutan salju, cat air lembut, palet biru-putih, potret, tanpa teks'). 3) Hasil pertama jarang yang terbaik — minta variasi, perbaiki instruksi, lalu SUNTING sendiri. Kalau ada fakta/angka (untuk artikel), CEK di sumber tepercaya; AI bisa mengarang. 4) Simpan yang 'inti & khas kamu' (cerita, gaya, pesan, eksekusi akhir) untuk dikerjakan sendiri; pakai AI untuk referensi, ide awal, & umpan balik. 5) Untuk tugas/lomba: ikuti aturan gurunya & jujurlah soal cara kamu memakai AI. Menyerahkan karya AI mentah sebagai buatan sendiri di lomba kreativitas itu curang. 6) Jangan minta AI meniru gaya PERSIS seniman tertentu, & jangan buat gambar wajah orang nyata tanpa izin — apalagi yang memalukan atau menyesatkan. 7) Kalau gambar AI-mu tampak seperti foto nyata & bisa disalahpahami, tulis 'gambar AI'. 8) Terus latih keterampilan yang ingin kamu kuasai (menggambar, menulis) SENDIRI — kalau AI selalu mengerjakan bagian sulit, kamu tidak akan berkembang di situ. 9) Kamu bertanggung jawab atas apa pun yang kamu buat & bagikan dengan AI — 'AI yang membuatnya' bukan alasan. 10) Kalau bingung apakah sesuatu pantas, tanya: 'apakah aku bersedia semua orang tahu bagaimana ini kubuat?'",explain:"Panduan baik menyederhanakan semua prinsip: cara kerja, instruksi yang baik, penyuntingan & verifikasi, menjaga visi & kontribusi, kejujuran & aturan, hormati hak & citra, menandai konten realistis, menjaga keterampilan, & tanggung jawab — dengan contoh ramah sebaya.",hint:"Tiap poin harus bisa langsung dipraktikkan teman sebayamu besok — konkret, dengan contoh."},
];
